var ch = Channel.CreateBounded<Job>(100);

async Task ProduceAsync()
{
    try
    {
        foreach (var job in jobs)
            await ch.Writer.WriteAsync(job);   // 100 queued — wait with no thread
    }
    finally { ch.Writer.Complete(); }          // without it consumers wait forever
}

async Task ConsumeAsync()
{
    await foreach (var job in ch.Reader.ReadAllAsync())   // each job goes to one
        await HandleAsync(job);                           // exits: completed and empty
}

var consumers = Enumerable.Range(0, 4).Select(_ => ConsumeAsync()).ToArray();
await Task.WhenAll(consumers.Append(ProduceAsync()));

