var gate = new SemaphoreSlim(8);   // 8 slots
var pages = await Task.WhenAll(urls.Select(async url =>
{
    await gate.WaitAsync();        // the 9th and later wait here, with no threads
    try     { return await DownloadAsync(url); }
    finally { gate.Release(); }    // the slot goes to the next one
}).ToArray());
